module math_problem_solver (input clk,input rst_n,input start,input [7:0] m,input [7:0] n,input [31:0] p,input [31:0] q,output reg [63:0] result,output reg found,output reg done);reg [63:0] current_prefix;reg [3:0] digits_p;reg [63:0] base_p;reg [63:0] min_X;reg [63:0] max_X;reg [63:0] temp;reg [63:0] X_candidate;reg [63:0] divisor;reg [63:0] Y_candidate;reg [2:0] state;reg [2:0] next_state;localparam [2:0] IDLE=3'b000,COMPUTE=3'b001,DONE=3'b100;localparam int [15:0] min_X_arr='{0,1,10,100,1000,10000,100000,1000000,10000000,100000000,1000000000,10000000000,100000000000,1000000000000,10000000000000,1000000000000000};localparam int [15:0] max_X_arr='{0,9,99,999,9999,99999,999999,9999999,99999999,999999999,9999999999,99999999999,999999999999,9999999999999,99999999999999,9999999999999999};localparam int [3:0] start_prefix_arr='{0,1,10,100};localparam int [3:0] end_prefix_arr='{0,9,99,999};function automatic [3:0] get_digits_p;input int p;if(p==0)return 4'd1;else if(p>=1000000000)return 4'd10;else if(p>=100000000)return 4'd9;else if(p>=10000000)return 4'd8;else if(p>=1000000)return 4'd7;else if(p>=100000)return 4'd6;else if(p>=10000)return 4'd5;else if(p>=1000)return 4'd4;else if(p>=100)return 4'd3;else if(p>=10)return 4'd2;else return 4'd1;endfunctionalways@(posedge clk)beginif(!rst_n)begincurrent_prefix<=0;digits_p<=0;base_p<=0;min_X<=0;max_X<=0;state<=IDLE;next_state<=IDLE;result<=0;found<=0;done<=0;endelsebeginif(state==IDLE)beginif(start)begindigits_p<=get_digits_p(p);base_p<=case(digits_p)4'd1:10;4'd2:100;4'd3:1000;4'd4:10000;4'd5:100000;4'd6:1000000;4'd7:10000000;4'd8:100000000;4'd9:1000000000;4'd10:10000000000;default:10;endcaseif(m>0&&m<=16)beginmin_X<=min_X_arr[m];max_X<=max_X_arr[m];endelsebeginmin_X<=1;max_X<=0;endif(n>3)begincurrent_prefix<=0;next_state<=DONE;endelsebegincurrent_prefix<=start_prefix_arr[n];next_state<=COMPUTE;endendelsebeginnext_state<=IDLE;endelseif(state==COMPUTE)beginif(current_prefix>end_prefix_arr[n])beginnext_state<=DONE;endelsebeginif(n>m)begincurrent_prefix<=current_prefix+1;next_state<=COMPUTE;endelsebeginint exp=m-n;int divisor;if(exp==0)divisor=1;else if(exp==1)divisor=10;else if(exp==2)divisor=100;else if(exp==3)divisor=1000;else if(exp==4)divisor=10000;else if(exp==5)divisor=100000;else if(exp==6)divisor=1000000;else if(exp==7)divisor=10000000;else if(exp==8)divisor=100000000;else if(exp==9)divisor=1000000000;else if(exp==10)divisor=10000000000;else if(exp==11)divisor=100000000000;else if(exp==12)divisor=1000000000000;else if(exp==13)divisor=10000000000000;else if(exp==14)divisor=100000000000000;else if(exp==15)divisor=1000000000000000;else divisor=1;temp=current_prefix*base_p+p;X_candidate=temp*q;if(X_candidate>=min_X&&X_candidate<=max_X)beginY_candidate=X_candidate/divisor;if(Y_candidate==current_prefix&&X_candidate==q*(Y_candidate*base_p+p))beginif(result==0||X_candidate<result)beginresult<=X_candidate;found<=1;endendendcurrent_prefix<=current_prefix+1;next_state<=COMPUTE;endendendendstate<=next_state;done<=(state==DONE);endassign found=found;assign done=done;endmodule